 13	 *   not a valid HTTPS URL (SSH, malformed, or empty).
 14	 */
 15	export function extractHost(url: string): string | null {
 16	    if (!url) return null;
 17	    try {
 18	        const parsed = new URL(url);
 19	        if (parsed.protocol !== 'https:') return null;
 20	        return parsed.hostname || null;
 21	    } catch {
 22	        return null;
 23	    }
 24	}
