 27	 * Injects a token credential into an HTTPS URL as the userinfo component.
 28	 *
 29	 * If the credentials map contains an entry whose key matches the URL's hostname,
 30	 * the token is inserted as `https://<token>@<host>/...`. If no matching entry
 31	 * exists, or the URL is not HTTPS, the original URL is returned unchanged.
 32	 *
 33	 * The token is written as the username only (no password component) since
 34	 * Personal Access Tokens are typically passed in the username field.
 35	 *
 36	 * **Security note:** Token injection is performed via WHATWG URL object property
 37	 * assignment (`parsed.username = token`), NOT string concatenation. The URL
 38	 * serialiser automatically percent-encodes special characters in the token (e.g.
 39	 * `@`, `/`, `#`), preventing URL injection even with adversarially-crafted values.
 40	 *
 41	 * @param url         - The remote URL to modify.
 42	 * @param credentials - Map of hostname → token (e.g. `{ "github.com": "ghp_abc" }`).
 43	 * @returns The URL with credentials injected, or the original URL if no match.
 44	 */
 45	export function injectCredentials(url: string, credentials: Record<string, string>): string {
